"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22679"],{93819(e){e.exports=JSON.parse('{"id":"FIN-020","slug":"saving-rate","term":"Saving Rate","also_known_as":[],"difficulty":"Beginner","definition":"The saving rate is the percentage of income that is saved rather than spent over a period, such as a month or a year.","explanation":["The saving rate shows how much of every unit of income is being put aside. It is calculated by dividing the amount saved by income and expressing the result as a percentage.","For example, if your take-home pay is 3,500 a month and you save 525, your saving rate is 15%. If you raise your savings to 700 without any change in income, your saving rate rises to 20%.","People sometimes calculate it using gross income and sometimes using net income, so it is worth being clear about which one is used. Using net income gives a higher percentage for the same amount saved.","The saving rate matters because it controls how quickly savings build up. Someone saving 10% of their income needs many more years to build a large fund than someone saving 25%. A higher saving rate also means lower spending, so the same savings last longer when they are eventually used.","Economists also track the household saving rate for a whole country. A rising national saving rate often signals that households are worried about the future and are cutting back on spending."],"note":"","total":1725,"prev":{"slug":"sarbanes-oxley-act","term":"Sarbanes-Oxley Act"},"next":{"slug":"savings","term":"Savings"}}')}}]);